    const i = t.indexOf('{'), j = t.lastIndexOf('}');
    if (i < 0 || j < i) return { ok: false, motivo: 'sin_json', crudo: lim(t, 300) };
    let o; try { o = JSON.parse(t.slice(i, j + 1)); } catch (x) { return { ok: false, motivo: 'json_invalido', crudo: lim(t, 300) }; }
