  const PIDE_DATOS_PAGO = /\balias\b|\bcbu\b|\bcvu\b|datos\s+(?:para\s+(?:transferir|la\s+transferencia|pagar)|bancarios|de\s+(?:la\s+)?cuenta|de\s+pago)|n[uú]mero\s+de\s+cuenta/i;
