        plan.fija = fijas.has('presentacion_anuncio') ? 'anuncio' : fijas.has('menu_bienvenida') ? 'menu' : fijas.has('pedir_texto') ? 'pedir_texto' : fijas.has('no_reply') ? 'no_reply' : 'no_entendi';
