  }
  const COD_TURNOS = ['FUERA_DE_ALCANCE', 'URGENCIA', 'PREGUNTA_PARA_QUIEN', 'PREGUNTA_DATOS_NUEVO', 'PREGUNTA_CUAL_TURNO', 'MOSTRAR_TURNOS', '[NO_REPLY]', '[LISTO]'];
