  const lista = (ts) => ts.map((t) => '- ' + t).join('\n');

  // Qué le dice al paciente cada resultado de herramienta de TURNOS (texto del código; nada sale del modelo).
  function textoTurnos(p) {
    const o = p.obs || {};
    if (p.tool === 'buscar_horarios') {
