    if (ef && ef.pregunta && !readback && !(g && g.texto)) pregunta = pregunta || ef.pregunta;
    if (!readback && !pregunta && !confPregunto && !confSinTurno && cod && cod.startsWith('PREGUNTA_')) pregunta = cod.slice('PREGUNTA_'.length);
